setup_files.item.py:
from pydantic import BaseModel, Field


class Item(BaseModel):
    code: str = Field(regex=r"^[A-Z]{3}$")

test_setup_files.test_item.py:
from item import Item

i = Item(code="ABC")
assert i.code == "ABC"

for bad in ["AB", "ABCD", "abc", "XABCX"]:
    try:
        Item(code=bad)
        raise AssertionError(f"expected {bad!r} to be rejected (not exactly 3 uppercase letters)")
    except AssertionError:
        raise
    except Exception:
        pass

print("PASS")

